-- The core's results against the reference's: every difference is listed, the first ones printed with the FAIL line.
-- Every comparison is null-safe (one side unknown and the other known is a difference) and every row is matched both
-- ways (review B2).
DECLARE @Id VARCHAR(10) = 'CE5', @Key VARCHAR(60) = 'G05_HALF_CAPITAL_LOST';
BEGIN
    DECLARE @err NVARCHAR(4000) = NULL;
    BEGIN TRY
        EXEC fin.usp_CreditCore;
    END TRY
    BEGIN CATCH
        SET @err = CONCAT('error ', ERROR_NUMBER(), ' line ', ERROR_LINE(), ': ', ERROR_MESSAGE());
    END CATCH;
    DECLARE @d TABLE (n INT IDENTITY, t NVARCHAR(400) COLLATE DATABASE_DEFAULT);
    IF @err IS NOT NULL
        INSERT @d (t) VALUES (@err);
    ELSE
    BEGIN
        -- two numbers agree when both are unknown, or they differ by less than a millionth of the larger (and of one unit)
        INSERT @d (t)
        SELECT CONCAT('quantity ', COALESCE(e.Code, q.Code), ' ', CONVERT(VARCHAR(30), e.Value, 3), ' <> ', CONVERT(VARCHAR(30), q.Value, 3),
                      CASE WHEN e.Code IS NULL THEN ' not expected' WHEN q.Code IS NULL THEN ' missing' END)
        FROM #eQ AS e FULL JOIN #crQ AS q ON q.Code = e.Code
        WHERE e.Code IS NULL OR q.Code IS NULL OR ((e.Value) IS NULL AND (q.Value) IS NOT NULL OR (e.Value) IS NOT NULL AND (q.Value) IS NULL OR ABS((e.Value) - (q.Value)) > 1e-6 * (1 + CASE WHEN ABS(e.Value) > ABS(q.Value) THEN ABS(e.Value) ELSE ABS(q.Value) END));
        INSERT @d (t)
        SELECT CONCAT('metric ', COALESCE(e.Code, m.Code), ' ', ISNULL(e.State, 'not expected'), ' ', CONVERT(VARCHAR(30), e.Value, 3), ' <> ', ISNULL(m.State, 'missing'), ' ',
                      CONVERT(VARCHAR(30), m.Value, 3))
        FROM #eM AS e FULL JOIN #crM AS m ON m.Code = e.Code
        WHERE e.Code IS NULL OR m.Code IS NULL OR ((e.State) IS NULL AND (m.State) IS NOT NULL OR (e.State) IS NOT NULL AND (m.State) IS NULL OR (e.State) <> (m.State))
           OR ((e.Value) IS NULL AND (m.Value) IS NOT NULL OR (e.Value) IS NOT NULL AND (m.Value) IS NULL OR ABS((e.Value) - (m.Value)) > 1e-6 * (1 + CASE WHEN ABS(e.Value) > ABS(m.Value) THEN ABS(e.Value) ELSE ABS(m.Value) END));
        INSERT @d (t)
        SELECT CONCAT('factor ', COALESCE(e.Code, f.Code), ' score ', e.Score, ' <> ', f.Score, ' weight ', e.EffectiveWeight, ' <> ', f.EffectiveWeight)
        FROM #eF AS e FULL JOIN #crF AS f ON f.Code = e.Code
        WHERE e.Code IS NULL OR f.Code IS NULL OR ((e.Score) IS NULL AND (f.Score) IS NOT NULL OR (e.Score) IS NOT NULL AND (f.Score) IS NULL OR ABS((e.Score) - (f.Score)) > 1e-4)
           OR ((e.EffectiveWeight) IS NULL AND (f.EffectiveWeight) IS NOT NULL OR (e.EffectiveWeight) IS NOT NULL AND (f.EffectiveWeight) IS NULL OR ABS((e.EffectiveWeight) - (f.EffectiveWeight)) > 1e-6);
        INSERT @d (t)
        SELECT CONCAT('item ', COALESCE(e.MetricCode, i.MetricCode), '/', COALESCE(e.LineCode, i.LineCode), ' ', ISNULL(e.Level, 'not expected'), ' ',
                      CONVERT(VARCHAR(30), e.Value, 3), ' <> ', ISNULL(i.Level, 'missing'), ' ', CONVERT(VARCHAR(30), i.Value, 3))
        FROM #eI AS e FULL JOIN #crI AS i ON i.MetricCode = e.MetricCode AND i.LineCode = e.LineCode
        WHERE e.MetricCode IS NULL OR i.MetricCode IS NULL OR ((e.Level) IS NULL AND (i.Level) IS NOT NULL OR (e.Level) IS NOT NULL AND (i.Level) IS NULL OR (e.Level) <> (i.Level))
           OR ((e.Value) IS NULL AND (i.Value) IS NOT NULL OR (e.Value) IS NOT NULL AND (i.Value) IS NULL OR ABS((e.Value) - (i.Value)) > 1e-6 * (1 + CASE WHEN ABS(e.Value) > ABS(i.Value) THEN ABS(e.Value) ELSE ABS(i.Value) END));
        INSERT @d (t)
        SELECT CONCAT('adjustment ', COALESCE(e.RuleCode, a.RuleCode), CASE WHEN a.RuleCode IS NULL THEN ' expected' WHEN e.RuleCode IS NULL THEN ' not expected' END,
                      ' notches ', e.Notches, '/', a.Notches, ' cap ', e.CapNotch, '/', a.CapNotch)
        FROM #eA AS e FULL JOIN #crA AS a ON a.RuleCode = e.RuleCode
        WHERE e.RuleCode IS NULL OR a.RuleCode IS NULL OR ((e.Notches) IS NULL AND (a.Notches) IS NOT NULL OR (e.Notches) IS NOT NULL AND (a.Notches) IS NULL OR (e.Notches) <> (a.Notches))
           OR ((e.CapNotch) IS NULL AND (a.CapNotch) IS NOT NULL OR (e.CapNotch) IS NOT NULL AND (a.CapNotch) IS NULL OR (e.CapNotch) <> (a.CapNotch));
        IF (SELECT COUNT(*) FROM #crS) <> 1
            INSERT @d (t) VALUES (CONCAT('summary rows ', (SELECT COUNT(*) FROM #crS), ', expected one'));
        INSERT @d (t)
        SELECT CONCAT('summary ', e.State, '/', s.State, ' coverage ', e.Coverage, '/', s.Coverage, ' completeness ', e.Completeness, '/', s.Completeness,
                      ' liquidity ', e.Liquidity, '/', s.Liquidity, ' financial ', e.FinancialScore, '/', s.FinancialScore, ' aggregate ', e.WeightedScore,
                      '/', s.WeightedScore, ' final ', e.FinalNotch, '/', s.FinalNotch, ' notches ', e.Notches, '/', s.Notches, ' facility ',
                      e.FacilityBand, ' ', e.FacilityLgd, ' ', e.FacilityNotch, '/', s.FacilityBand, ' ', s.FacilityLgd, ' ', s.FacilityNotch)
        FROM #eS AS e LEFT JOIN #crS AS s ON 1 = 1
        WHERE s.State IS NULL OR ((e.State) IS NULL AND (s.State) IS NOT NULL OR (e.State) IS NOT NULL AND (s.State) IS NULL OR (e.State) <> (s.State))
           OR ((e.Coverage) IS NULL AND (s.Coverage) IS NOT NULL OR (e.Coverage) IS NOT NULL AND (s.Coverage) IS NULL OR ABS((e.Coverage) - (s.Coverage)) > 0.01)
           OR ((e.Completeness) IS NULL AND (s.Completeness) IS NOT NULL OR (e.Completeness) IS NOT NULL AND (s.Completeness) IS NULL OR ABS((e.Completeness) - (s.Completeness)) > 0.01)
           OR ((e.Liquidity) IS NULL AND (s.Liquidity) IS NOT NULL OR (e.Liquidity) IS NOT NULL AND (s.Liquidity) IS NULL OR (e.Liquidity) <> (s.Liquidity))
           OR ((e.FinancialScore) IS NULL AND (s.FinancialScore) IS NOT NULL OR (e.FinancialScore) IS NOT NULL AND (s.FinancialScore) IS NULL OR ABS((e.FinancialScore) - (s.FinancialScore)) > 1e-4)
           OR ((e.WeightedScore) IS NULL AND (s.WeightedScore) IS NOT NULL OR (e.WeightedScore) IS NOT NULL AND (s.WeightedScore) IS NULL OR ABS((e.WeightedScore) - (s.WeightedScore)) > 1e-4)
           OR ((e.FinalNotch) IS NULL AND (s.FinalNotch) IS NOT NULL OR (e.FinalNotch) IS NOT NULL AND (s.FinalNotch) IS NULL OR (e.FinalNotch) <> (s.FinalNotch))
           OR ((e.Notches) IS NULL AND (s.Notches) IS NOT NULL OR (e.Notches) IS NOT NULL AND (s.Notches) IS NULL OR (e.Notches) <> (s.Notches))
           OR ((e.FacilityBand) IS NULL AND (s.FacilityBand) IS NOT NULL OR (e.FacilityBand) IS NOT NULL AND (s.FacilityBand) IS NULL OR (e.FacilityBand) <> (s.FacilityBand))
           OR ((e.FacilityNotch) IS NULL AND (s.FacilityNotch) IS NOT NULL OR (e.FacilityNotch) IS NOT NULL AND (s.FacilityNotch) IS NULL OR (e.FacilityNotch) <> (s.FacilityNotch))
           OR ((e.FacilityLgd) IS NULL AND (s.FacilityLgd) IS NOT NULL OR (e.FacilityLgd) IS NOT NULL AND (s.FacilityLgd) IS NULL OR ABS((e.FacilityLgd) - (s.FacilityLgd)) > 1e-4);
    END;
    DECLARE @n INT = (SELECT COUNT(*) FROM @d), @first NVARCHAR(4000);
    SELECT @first = STRING_AGG(t, '; ') WITHIN GROUP (ORDER BY n) FROM @d WHERE n <= 6;
    IF @n = 0
        PRINT CONCAT('PASS ', @Id, ': ', @Key, ' - the core equals the reference');
    ELSE
        PRINT CONCAT('FAIL ', @Id, ': ', @Key, ' - ', @n, ' differences: ', @first);
END;

GO

