    BEGIN TRY
        EXEC fin.usp_CreditEvaluate @WithScenarios = 1, @WithRemedies = 1, @WithPlans = 1;
    END TRY
    BEGIN CATCH
        SET @err = CONCAT('error ', ERROR_NUMBER(), ' ', ERROR_PROCEDURE(), ' line ', ERROR_LINE(), ': ', ERROR_MESSAGE());
    END CATCH;
    DECLARE @d TABLE (n INT IDENTITY, t NVARCHAR(400) COLLATE DATABASE_DEFAULT);
    IF @err IS NOT NULL
        INSERT @d (t) VALUES (@err);
    ELSE
    BEGIN
        IF (SELECT COUNT(*) FROM #crS) <> 1 OR (SELECT COUNT(*) FROM #evSum) <> 1
            INSERT @d (t) VALUES (CONCAT('summary rows ', (SELECT COUNT(*) FROM #crS), '/', (SELECT COUNT(*) FROM #evSum), ', expected one each'));
        INSERT @d (t)
        SELECT CONCAT('result ', e.State, '/', s.State, ' final ', e.FinalNotch, '/', s.FinalNotch, ' resilience ', e.Resilience, '/', v.Resilience,
                      ' outlook ', e.Outlook, ' ', e.OutlookRules, '/', v.Outlook, ' ', v.OutlookRules)
        FROM #eEv AS e LEFT JOIN #crS AS s ON 1 = 1 LEFT JOIN #evSum AS v ON 1 = 1
        WHERE s.State IS NULL OR ((e.State) IS NULL AND (s.State) IS NOT NULL OR (e.State) IS NOT NULL AND (s.State) IS NULL OR (e.State) <> (s.State))
           OR ((e.FinalNotch) IS NULL AND (s.FinalNotch) IS NOT NULL OR (e.FinalNotch) IS NOT NULL AND (s.FinalNotch) IS NULL OR (e.FinalNotch) <> (s.FinalNotch))
           OR ((e.Resilience) IS NULL AND (v.Resilience) IS NOT NULL OR (e.Resilience) IS NOT NULL AND (v.Resilience) IS NULL OR (e.Resilience) <> (v.Resilience))
           OR ((e.Outlook) IS NULL AND (v.Outlook) IS NOT NULL OR (e.Outlook) IS NOT NULL AND (v.Outlook) IS NULL OR (e.Outlook) <> (v.Outlook))
           OR ((e.OutlookRules) IS NULL AND (v.OutlookRules) IS NOT NULL OR (e.OutlookRules) IS NOT NULL AND (v.OutlookRules) IS NULL OR (e.OutlookRules) <> (v.OutlookRules));
        INSERT @d (t)
        SELECT CONCAT('scenario ', COALESCE(e.Scenario, x.Scenario), ' ', e.FinalNotch, ' lost ', e.NotchesLost, ' ', e.Liquidity, ' / ', x.FinalNotch, ' lost ',
                      x.NotchesLost, ' ', x.Liquidity)
        FROM #eScen AS e FULL JOIN #evScen AS x ON x.Scenario = e.Scenario
        WHERE e.Scenario IS NULL OR x.Scenario IS NULL OR ((e.FinalNotch) IS NULL AND (x.FinalNotch) IS NOT NULL OR (e.FinalNotch) IS NOT NULL AND (x.FinalNotch) IS NULL OR (e.FinalNotch) <> (x.FinalNotch))
           OR ((e.NotchesLost) IS NULL AND (x.NotchesLost) IS NOT NULL OR (e.NotchesLost) IS NOT NULL AND (x.NotchesLost) IS NULL OR (e.NotchesLost) <> (x.NotchesLost))
           OR ((e.Liquidity) IS NULL AND (x.Liquidity) IS NOT NULL OR (e.Liquidity) IS NOT NULL AND (x.Liquidity) IS NULL OR (e.Liquidity) <> (x.Liquidity))
           OR ((e.RevenuePct) IS NULL AND (x.RevenuePct) IS NOT NULL OR (e.RevenuePct) IS NOT NULL AND (x.RevenuePct) IS NULL OR ABS((e.RevenuePct) - (x.RevenuePct)) > 1e-6)
           OR ((e.DsoDays) IS NULL AND (x.DsoDays) IS NOT NULL OR (e.DsoDays) IS NOT NULL AND (x.DsoDays) IS NULL OR ABS((e.DsoDays) - (x.DsoDays)) > 1e-6)
           OR ((e.StLinesWithdrawnPct) IS NULL AND (x.StLinesWithdrawnPct) IS NOT NULL OR (e.StLinesWithdrawnPct) IS NOT NULL AND (x.StLinesWithdrawnPct) IS NULL OR ABS((e.StLinesWithdrawnPct) - (x.StLinesWithdrawnPct)) > 1e-6)
           OR ((e.PrivateArLossPct) IS NULL AND (x.PrivateArLossPct) IS NOT NULL OR (e.PrivateArLossPct) IS NOT NULL AND (x.PrivateArLossPct) IS NULL OR ABS((e.PrivateArLossPct) - (x.PrivateArLossPct)) > 1e-6)
           OR ((e.InventoryWritedownPct) IS NULL AND (x.InventoryWritedownPct) IS NOT NULL OR (e.InventoryWritedownPct) IS NOT NULL AND (x.InventoryWritedownPct) IS NULL OR ABS((e.InventoryWritedownPct) - (x.InventoryWritedownPct)) > 1e-6)
           OR ((e.UndrawnAvailablePct) IS NULL AND (x.UndrawnAvailablePct) IS NOT NULL OR (e.UndrawnAvailablePct) IS NOT NULL AND (x.UndrawnAvailablePct) IS NULL OR ABS((e.UndrawnAvailablePct) - (x.UndrawnAvailablePct)) > 1e-6)
           OR ((e.CountryMult) IS NULL AND (x.CountryMult) IS NOT NULL OR (e.CountryMult) IS NOT NULL AND (x.CountryMult) IS NULL OR ABS((e.CountryMult) - (x.CountryMult)) > 1e-6)
           OR ((e.LenderCostBp) IS NULL AND (x.LenderCostBp) IS NOT NULL OR (e.LenderCostBp) IS NOT NULL AND (x.LenderCostBp) IS NULL OR ABS((e.LenderCostBp) - (x.LenderCostBp)) > 1e-6);
        INSERT @d (t)
        SELECT CONCAT('remedy ', COALESCE(e.Code, r.Code), ' ', e.TriggerCode, ' ', e.TriggerLevel, ' ', CONVERT(VARCHAR(30), e.Moved, 3), ' ', e.FinalNotch, ' ', e.NotchesGained,
                      ' / ', x.TriggerCode, ' ', x.TriggerLevel, ' ', CONVERT(VARCHAR(30), x.Moved, 3), ' ', x.FinalNotch, ' ', x.NotchesGained)
        FROM #eRem AS e
        FULL JOIN (#evRem AS x JOIN fin.CreditRemedy AS r ON r.CreditRemedyId = x.RemedyId) ON r.Code = e.Code
        WHERE e.Code IS NULL OR r.Code IS NULL OR ((e.TriggerCode) IS NULL AND (x.TriggerCode) IS NOT NULL OR (e.TriggerCode) IS NOT NULL AND (x.TriggerCode) IS NULL OR (e.TriggerCode) <> (x.TriggerCode))
           OR ((e.TriggerLevel) IS NULL AND (x.TriggerLevel) IS NOT NULL OR (e.TriggerLevel) IS NOT NULL AND (x.TriggerLevel) IS NULL OR (e.TriggerLevel) <> (x.TriggerLevel))
           OR ((e.FinalNotch) IS NULL AND (x.FinalNotch) IS NOT NULL OR (e.FinalNotch) IS NOT NULL AND (x.FinalNotch) IS NULL OR (e.FinalNotch) <> (x.FinalNotch))
           OR ((e.NotchesGained) IS NULL AND (x.NotchesGained) IS NOT NULL OR (e.NotchesGained) IS NOT NULL AND (x.NotchesGained) IS NULL OR (e.NotchesGained) <> (x.NotchesGained))
           OR ((e.Moved) IS NULL AND (x.Moved) IS NOT NULL OR (e.Moved) IS NOT NULL AND (x.Moved) IS NULL OR ABS((e.Moved) - (x.Moved)) > 1e-6 * (1 + CASE WHEN ABS(e.Moved) > ABS(x.Moved) THEN ABS(e.Moved) ELSE ABS(x.Moved) END));
        INSERT @d (t)
        SELECT CONCAT('plan ', COALESCE(e.Code, p.Code), ' ', e.FinalNotch, ' +', e.NotchesGained, ' ', e.Steps, ' / ', x.FinalNotch, ' +', x.NotchesGained, ' ', st.Steps,
                      ' balanced ', e.IsBalanced, '/', x.IsBalanced)
        FROM #ePlan AS e
        FULL JOIN (#evPlan AS x JOIN fin.StrengtheningPlan AS p ON p.StrengtheningPlanId = x.PlanId) ON p.Code = e.Code
        OUTER APPLY (SELECT STRING_AGG(r.Code, ',') WITHIN GROUP (ORDER BY s.StepNo) AS Steps FROM #evPlanStep AS s
                     JOIN fin.CreditRemedy AS r ON r.CreditRemedyId = s.RemedyId WHERE s.PlanId = x.PlanId) AS st
        WHERE e.Code IS NULL OR p.Code IS NULL OR ((e.FinalNotch) IS NULL AND (x.FinalNotch) IS NOT NULL OR (e.FinalNotch) IS NOT NULL AND (x.FinalNotch) IS NULL OR (e.FinalNotch) <> (x.FinalNotch))
           OR ((e.NotchesGained) IS NULL AND (x.NotchesGained) IS NOT NULL OR (e.NotchesGained) IS NOT NULL AND (x.NotchesGained) IS NULL OR (e.NotchesGained) <> (x.NotchesGained))
           OR ((e.Steps) IS NULL AND (st.Steps) IS NOT NULL OR (e.Steps) IS NOT NULL AND (st.Steps) IS NULL OR (e.Steps) <> (st.Steps))
           OR ((e.IsBalanced) IS NULL AND (x.IsBalanced) IS NOT NULL OR (e.IsBalanced) IS NOT NULL AND (x.IsBalanced) IS NULL OR (e.IsBalanced) <> (x.IsBalanced));
        INSERT @d (t)
        SELECT CONCAT('trigger ', COALESCE(e.MetricCode, x.MetricCode), ' ', COALESCE(e.Direction, x.Direction), ' ', CONVERT(VARCHAR(30), e.TriggerValue, 3), ' / ',
                      CONVERT(VARCHAR(30), x.TriggerValue, 3))
        FROM #eTrig AS e FULL JOIN #evTrig AS x ON x.MetricCode = e.MetricCode AND x.Direction = e.Direction
        -- a trigger agrees when its value does, or its target score does to a thousandth: the weighted score is rounded to
        -- four decimals on both sides, and a steep grid turns its last digit into a visible difference of value
        WHERE e.MetricCode IS NULL OR x.MetricCode IS NULL
           OR (((e.TriggerValue) IS NULL AND (x.TriggerValue) IS NOT NULL OR (e.TriggerValue) IS NOT NULL AND (x.TriggerValue) IS NULL OR ABS((e.TriggerValue) - (x.TriggerValue)) > 1e-5 * (1 + CASE WHEN ABS(e.TriggerValue) > ABS(x.TriggerValue) THEN ABS(e.TriggerValue) ELSE ABS(x.TriggerValue) END))
               AND ((e.TargetScore) IS NULL AND (x.TargetScore) IS NOT NULL OR (e.TargetScore) IS NOT NULL AND (x.TargetScore) IS NULL OR ABS((e.TargetScore) - (x.TargetScore)) > 1e-3));
    END;
    DECLARE @n INT = (SELECT COUNT(*) FROM @d), @first NVARCHAR(4000);
    SELECT @first = STRING_AGG(t, '; ') WITHIN GROUP (ORDER BY n) FROM @d WHERE n <= 6;
    IF @n = 0
        PRINT CONCAT('PASS ', @Id, ': ', @Key, ' - the evaluation equals the reference');
    ELSE
        PRINT CONCAT('FAIL ', @Id, ': ', @Key, ' - ', @n, ' differences: ', @first);
END;

GO

